<div class="page-heading"><div><span class="eyebrow">Diagnóstico</span><h1>Laboratorio clínico</h1><p>Solicitudes, resultados y documentos PDF.</p></div><button class="btn btn-primary" data-modal-open="lab-create">＋ Examen</button></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><section class="card"><div class="table-wrap"><table class="modern-table"><thead><tr><th>Fecha</th><th>Paciente</th><th>Tipo</th><th>Resultado</th></tr></thead><tbody><?php foreach($exams as $x):?><tr><td><?=e($x['fecha_solicitud'])?></td><td><?=e($x['paciente'])?></td><td><?=e($x['tipo'])?></td><td><?=e($x['resultado_resumen']??'Pendiente')?></td></tr><?php endforeach;?></tbody></table></div></section><div class="modal" id="lab-create"><div class="modal-backdrop"></div><div class="modal-dialog modal-lg"><div class="modal-header"><h2>Nuevo examen</h2><button class="modal-close" data-modal-close>×</button></div><form method="POST" enctype="multipart/form-data" action="<?=url('/laboratorio')?>"><?=csrf_field()?><div class="modal-body form-grid"><label><span>Paciente</span><select name="animal_id" required><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['nombre'])?></option><?php endforeach;?></select></label><label><span>Tipo</span><select name="tipo_examen_id" required><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=e($t['nombre'])?></option><?php endforeach;?></select></label><label><span>Fecha solicitud</span><input type="datetime-local" name="fecha_solicitud"></label><label><span>Fecha resultado</span><input type="datetime-local" name="fecha_resultado"></label><label class="field-full"><span>Resumen resultado</span><textarea name="resultado_resumen"></textarea></label><label class="field-full"><span>PDF / imagen</span><input type="file" name="archivo" accept="application/pdf,image/*"></label></div><div class="modal-footer"><button class="btn btn-primary">Guardar</button></div></form></div></div>
